-- Israel: milestone translations (ES/DE/FR) for the 5 milestones
-- introduced in 273_israel_milestones.sql. INSERT OR IGNORE throughout
-- (idempotent), following the exact pattern of
-- 266_jordan_milestone_translations.sql.

-- il-law-enacted
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-law-enacted', 'es', 'Se promulga la Ley de Eficiencia Económica, que introduce el sistema de compensación', 'La Ley de Eficiencia Económica (Enmiendas Presupuestarias) de Israel para 2023-2024 modificó la Ley del IVA de 1975 para introducir un sistema de compensación de facturas en tiempo real mediante disposiciones temporales, facultando al Ministerio de Finanzas para prorrogar el régimen. La ley entró en vigor el 1 de enero de 2024, aunque su implementación se pospuso debido a la situación de seguridad del momento.', '["Todavía no se requiere ninguna acción -- esta es la base legal sobre la que se construyen las fases obligatorias posteriores", "Las grandes empresas registradas a efectos del IVA deberían empezar a seguir las directrices de la Autoridad Tributaria de Israel (ITA) antes de la fase piloto"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-law-enacted', 'de', 'Gesetz zur wirtschaftlichen Effizienz verabschiedet, führt Freigabesystem ein', 'Israels Gesetz zur wirtschaftlichen Effizienz (Haushaltsänderungen) für 2023-2024 änderte das Mehrwertsteuergesetz von 1975 und führte über befristete Bestimmungen ein Echtzeit-Rechnungsfreigabesystem ein; das Finanzministerium wurde ermächtigt, die Regelung zu verlängern. Das Gesetz trat am 1. Januar 2024 in Kraft, die Umsetzung wurde jedoch aufgrund der damaligen Sicherheitslage verschoben.', '["Noch keine Handlung erforderlich -- dies ist die rechtliche Grundlage, auf der die späteren verpflichtenden Phasen aufbauen", "Große umsatzsteuerpflichtige Unternehmen sollten die Richtlinien der israelischen Steuerbehörde (ITA) bereits vor der Pilotphase beobachten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-law-enacted', 'fr', 'Adoption de la loi sur l''efficacité économique, instaurant le système de validation', 'La loi israélienne sur l''efficacité économique (amendements budgétaires) pour 2023-2024 a modifié la loi sur la TVA de 1975 afin d''introduire, via des dispositions temporaires, un système de validation des factures en temps réel, le ministère des Finances étant habilité à prolonger ce régime. La loi est entrée en vigueur le 1er janvier 2024, bien que sa mise en œuvre ait été reportée en raison de la situation sécuritaire de l''époque.', '["Aucune action requise pour l''instant -- il s''agit du fondement juridique sur lequel reposent les phases obligatoires ultérieures", "Les grandes entreprises assujetties à la TVA devraient commencer à suivre les directives de l''Autorité fiscale israélienne (ITA) avant la phase pilote"]');

-- il-pilot-25k
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-pilot-25k', 'es', 'Comienza la fase piloto -- se exige número de asignación por encima de 25.000 NIS', 'La plataforma de compensación SHAAM entró en funcionamiento para facturas B2B nacionales que superasen los 25.000 NIS (sin IVA). Se trató de un piloto genuino: toda solicitud válida recibió un número de asignación automáticamente durante 2024, sin rechazos por motivos de contenido, dando a las empresas un período de bajo riesgo para desarrollar sus procesos de envío.', '["Si emite facturas B2B por encima de 25.000 NIS, empiece a enviarlas a través de SHAAM -- mediante integración directa por API o el portal manual de la ITA", "Adapte ya sus datos de facturación a los campos requeridos, ya que el control se intensifica a partir de 2025"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-pilot-25k', 'de', 'Pilotphase beginnt -- Zuteilungsnummer ab 25.000 NIS erforderlich', 'Die SHAAM-Freigabeplattform ging für inländische B2B-Rechnungen über 25.000 NIS (ohne Mehrwertsteuer) live. Es handelte sich um eine echte Pilotphase: Jede gültige Anfrage erhielt 2024 automatisch eine Zuteilungsnummer, ohne inhaltliche Ablehnungen -- ein risikoarmer Zeitraum für Unternehmen, um Einreichungsprozesse aufzubauen.', '["Wenn Sie B2B-Rechnungen über 25.000 NIS ausstellen, beginnen Sie mit der Übermittlung über SHAAM -- entweder per direkter API-Integration oder über das manuelle Portal der ITA", "Bilden Sie Ihre Rechnungsdaten bereits jetzt auf die erforderlichen Felder ab, da die Prüfung ab 2025 strenger wird"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-pilot-25k', 'fr', 'Début de la phase pilote -- numéro d''allocation requis au-delà de 25 000 NIS', 'La plateforme de validation SHAAM est entrée en service pour les factures B2B nationales dépassant 25 000 NIS (hors TVA). Il s''agissait d''un véritable pilote : toute demande valide a reçu automatiquement un numéro d''allocation en 2024, sans rejet pour des raisons de contenu, laissant aux entreprises une période à faible risque pour bâtir leurs processus de soumission.', '["Si vous émettez des factures B2B supérieures à 25 000 NIS, commencez à les soumettre via SHAAM -- par intégration API directe ou via le portail manuel de l''ITA", "Adaptez dès maintenant vos données de facturation aux champs requis, le contrôle se renforçant à partir de 2025"]');

-- il-phase2-20k
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase2-20k', 'es', 'El umbral baja a 20.000 NIS -- se activan plenos poderes de control', 'El umbral obligatorio bajó a 20.000 NIS, y terminó el período de gracia sin rechazos del piloto: la ITA obtuvo la capacidad de examinar los envíos y rechazar números de asignación para facturas que considere irregulares, con un proceso formal de revisión y audiencia disponible en un plazo de 2 días hábiles tras un rechazo.', '["Confirme que toda factura B2B por encima de 20.000 NIS lleva un número de asignación válido antes de utilizarla para la deducción del IVA", "Revise la calidad de los datos de sus envíos -- las facturas de apariencia irregular ahora pueden ser rechazadas de verdad, no solo marcadas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase2-20k', 'de', 'Schwelle sinkt auf 20.000 NIS -- volle Kontrollbefugnisse aktiviert', 'Die verpflichtende Schwelle sank auf 20.000 NIS, und die ablehnungsfreie Übergangsfrist der Pilotphase endete: Die ITA erhielt die Befugnis, Einreichungen zu prüfen und Zuteilungsnummern für als unregelmäßig eingestufte Rechnungen abzulehnen, mit einem formellen Überprüfungs- und Anhörungsverfahren innerhalb von 2 Werktagen nach einer Ablehnung.', '["Stellen Sie sicher, dass jede B2B-Rechnung über 20.000 NIS eine gültige Zuteilungsnummer trägt, bevor Sie sich für den Vorsteuerabzug darauf verlassen", "Überprüfen Sie die Datenqualität Ihrer Einreichungen -- unregelmäßig wirkende Rechnungen können jetzt tatsächlich abgelehnt werden, nicht nur markiert werden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase2-20k', 'fr', 'Le seuil passe à 20 000 NIS -- pleins pouvoirs de contrôle activés', 'Le seuil obligatoire est passé à 20 000 NIS, mettant fin à la période de grâce sans rejet du pilote : l''ITA a obtenu la capacité d''examiner les soumissions et de refuser des numéros d''allocation pour les factures jugées irrégulières, avec une procédure formelle de révision et d''audience disponible dans un délai de 2 jours ouvrés après un refus.', '["Vérifiez que chaque facture B2B supérieure à 20 000 NIS porte un numéro d''allocation valide avant de vous en servir pour la déduction de la TVA", "Revoyez la qualité des données de vos soumissions -- les factures d''apparence irrégulière peuvent désormais être réellement refusées, et non plus seulement signalées"]');

-- il-phase3-10k
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase3-10k', 'es', 'Descenso acelerado del umbral a 10.000 NIS', 'El umbral bajó a 10.000 NIS, saltándose el escalón de 15.000 NIS previsto originalmente -- parte de una aceleración de diciembre de 2025 (Orden de Aplicación del IVA 01/2025) que comprimió lo que se había legislado como un despliegue de cinco años hasta 2028 en solo dos años, terminando a mediados de 2026.', '["Vuelva a comprobar si las facturas que antes consideraba por debajo del umbral ahora requieren un número de asignación", "Si aún no se ha integrado por API, la vía del portal manual resulta cada vez menos práctica a medida que más volumen de facturación entra en el ámbito de aplicación"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase3-10k', 'de', 'Beschleunigte Schwellenabsenkung auf 10.000 NIS', 'Die Schwelle sank auf 10.000 NIS und übersprang damit die ursprünglich geplante Zwischenstufe von 15.000 NIS -- Teil einer im Dezember 2025 beschlossenen Beschleunigung (Mehrwertsteuer-Durchführungsverordnung 01/2025), die den ursprünglich als fünfjährigen Rollout bis 2028 gesetzlich vorgesehenen Zeitplan auf zwei Jahre verkürzte und Mitte 2026 abschließt.', '["Überprüfen Sie erneut, ob Rechnungen, die Sie bisher als unterhalb der Schwelle behandelt haben, nun eine Zuteilungsnummer benötigen", "Falls Sie noch nicht per API integriert sind, wird der manuelle Portal-Weg zunehmend unpraktikabler, je mehr Ihres Rechnungsvolumens in den Anwendungsbereich fällt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase3-10k', 'fr', 'Baisse accélérée du seuil à 10 000 NIS', 'Le seuil est tombé à 10 000 NIS, sautant l''étape de 15 000 NIS initialement prévue -- dans le cadre d''une accélération de décembre 2025 (arrêté d''application de la TVA 01/2025) qui a comprimé en deux ans ce qui avait été légiféré comme un déploiement sur cinq ans jusqu''en 2028, pour s''achever mi-2026.', '["Vérifiez à nouveau si des factures que vous considériez auparavant sous le seuil nécessitent désormais un numéro d''allocation", "Si vous n''avez pas encore intégré l''API, la voie du portail manuel devient de moins en moins praticable à mesure qu''une plus grande part de votre volume de facturation entre dans le champ d''application"]');

-- il-phase4-5k
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase4-5k', 'es', 'Se alcanza el umbral final -- 5.000 NIS, el suelo permanente', 'El umbral alcanzó su nivel mínimo final y permanente de 5.000 NIS (sin IVA) -- por ahora no está prevista ninguna reducción adicional. Esto completa el despliegue acelerado aproximadamente 18 meses antes de lo legislado originalmente, e incorpora al ámbito de aplicación a la gran mayoría de las facturas B2B nacionales.', '["Confirme que sus sistemas gestionan números de asignación para prácticamente todas las facturas B2B por encima de 5.000 NIS -- esto ya es la norma, no una excepción", "Recuerde que las operaciones B2C, B2G y transfronterizas quedan fuera del ámbito de este mandato"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase4-5k', 'de', 'Endgültige Schwelle erreicht -- 5.000 NIS, die dauerhafte Untergrenze', 'Die Schwelle erreichte ihre endgültige, dauerhafte Untergrenze von 5.000 NIS (ohne Mehrwertsteuer) -- weitere Absenkungen sind derzeit nicht vorgesehen. Damit ist der beschleunigte Rollout rund 18 Monate früher abgeschlossen als ursprünglich gesetzlich vorgesehen, und die große Mehrheit der inländischen B2B-Rechnungen fällt nun in den Anwendungsbereich.', '["Stellen Sie sicher, dass Ihre Systeme Zuteilungsnummern für praktisch alle B2B-Rechnungen über 5.000 NIS verarbeiten -- dies ist jetzt der Regelfall, kein Randfall mehr", "Denken Sie daran, dass B2C-, B2G- und grenzüberschreitende Transaktionen außerhalb des Anwendungsbereichs dieses Mandats bleiben"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase4-5k', 'fr', 'Seuil final atteint -- 5 000 NIS, le plancher permanent', 'Le seuil a atteint son plancher final et permanent de 5 000 NIS (hors TVA) -- aucune nouvelle baisse n''est actuellement prévue. Cela achève le déploiement accéléré environ 18 mois plus tôt que ce qui était initialement légiféré, et fait entrer dans le champ d''application la grande majorité des factures B2B nationales.', '["Vérifiez que vos systèmes gèrent les numéros d''allocation pour pratiquement toutes les factures B2B supérieures à 5 000 NIS -- c''est désormais la norme, plus un cas particulier", "N''oubliez pas que les opérations B2C, B2G et transfrontalières restent hors du champ d''application de ce mandat"]');
